const messages = [
  { role: 'system', content: 'You are a strict code reviewer.' },
  { role: 'user', content: 'Review this function...' }
];

await client.chat.completions.create({
  model: 'gpt-4o-mini',
  temperature: 0.2,
  max_tokens: 300,
  messages
});

